DROP TABLE IF EXISTS `transit_hub_regions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transit_hub_regions` (
  `region_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `h3_res` tinyint unsigned DEFAULT NULL,
  `h3_cells` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `polygon` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`region_id`),
  CONSTRAINT `transit_hub_regions_chk_1` CHECK (json_valid(`h3_cells`)),
  CONSTRAINT `transit_hub_regions_chk_2` CHECK (json_valid(`polygon`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

